SELECT public.payroll_preparation_mutate('open','{"year":2026,"month":2,"workingDays":24}');
SELECT public.payroll_preparation_mutate('attendance_save',jsonb_build_object('year',2026,'month',2,'driverId','a9500000-0000-4000-8000-000000000005','expectedVersion',0,'note','Every calendar day reviewed','days',(SELECT jsonb_agg(jsonb_build_object('date',to_char(d,'YYYY-MM-DD'),'status',CASE WHEN extract(day FROM d)<=20 THEN 'present' WHEN extract(day FROM d)=21 THEN 'half_day' WHEN extract(day FROM d)=22 THEN 'absent_unexcused' ELSE 'day_off' END)) FROM generate_series('2026-02-01'::date,'2026-02-28'::date,'1 day') d)));
SELECT public.payroll_preparation_mutate('orders_review',jsonb_build_object('year',2026,'month',2,'driverId','a9500000-0000-4000-8000-000000000005','expectedVersion',(SELECT version FROM public.payroll_preparation_reviews WHERE driver_id='a9500000-0000-4000-8000-000000000005'),'delivered',0,'revenue',0,'note','Explicit zero orders confirmed'));
UPDATE payroll_fixture SET advance_id=(public.payroll_preparation_mutate('advance_save','{"driverId":"a9500000-0000-4000-8000-000000000005","requestId":"a9500000-0000-4000-8000-000000000009","amount":12.34,"advanceDate":"2026-02-01","repaymentMonth":"2026-02","reason":"Driver advance request"}')->>'id')::uuid;
SELECT public.payroll_preparation_mutate('advance_transition',jsonb_build_object('id',advance_id,'expectedVersion',1,'to','approved','note','Manager approved advance')) FROM payroll_fixture;
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('lock',jsonb_build_object('year',2026,'month',2,'expectedVersion',(SELECT preparation_version FROM public.attendance_periods WHERE tenant_id='a9500000-0000-4000-8000-000000000001' AND period_year=2026 AND period_month=2),'note','Owner reviewed every input'))$$,'Future hire does not prevent full-month driver preparation lock');
