INSERT INTO public.violations(id,tenant_id,driver_id,incident_date,incident_description,status,deduction_amount) VALUES('a9500000-0000-4000-8000-000000000011','a9500000-0000-4000-8000-000000000001','a9500000-0000-4000-8000-000000000005','2026-02-01','Reviewed violation','resolved',5.67);
INSERT INTO public.violation_deduction_ledger(tenant_id,driver_id,violation_id,deduction_month,deduction_amount) VALUES('a9500000-0000-4000-8000-000000000001','a9500000-0000-4000-8000-000000000005','a9500000-0000-4000-8000-000000000011','2026-02',5.67);
