SELECT lives_ok($$UPDATE payroll_fixture SET result=public.calculate_payroll_atomic('a9500000-0000-4000-8000-000000000005',2026,2)$$,'Caller-bound full-month calculation commits');
UPDATE payroll_fixture SET period_id=(result->>'id')::uuid;
SELECT is((SELECT (result->>'base_amount')::numeric FROM payroll_fixture),2306.46::numeric,'Exact decimal daily base rounds once');
SELECT is((SELECT (result->>'net_payroll')::numeric FROM payroll_fixture),2175.94::numeric,'Exact net includes explicit absence, advance and violation');
SELECT is((SELECT total_earnings FROM public.driver_payroll_periods WHERE id=(SELECT period_id FROM payroll_fixture)),2306.46::numeric,'Persisted earnings matches displayed formula');
SELECT is((SELECT jsonb_array_length(result->'deduction_lines') FROM payroll_fixture),2,'Persisted result names both financial deduction sources');
SELECT lives_ok($$SELECT public.calculate_payroll_atomic('a9500000-0000-4000-8000-000000000005',2026,2)$$,'Unapproved calculation may be recalculated safely');
SELECT is((SELECT count(*)::integer FROM public.driver_payroll_periods WHERE driver_id='a9500000-0000-4000-8000-000000000005'),1,'Retry does not create duplicate active payroll');
SELECT public.transition_payroll_status_atomic(period_id,'in_review') FROM payroll_fixture;
