INSERT INTO public.payroll_advances(id,tenant_id,driver_id,amount,advance_date,repayment_month,status) VALUES('a9500000-0000-4000-8000-000000000013','a9500000-0000-4000-8000-000000000001','a9500000-0000-4000-8000-000000000005',1,'2026-02-01','2026-02','approved');
