SELECT throws_ok($$SELECT public.transition_payroll_status_atomic(period_id,'approved') FROM payroll_fixture$$,'P0001','PAY_ADVANCE_SNAPSHOT_CHANGED','A newly approved advance invalidates a stale calculation before approval');
