SELECT throws_ok($$SELECT public.transition_payroll_status_atomic(period_id,'approved') FROM payroll_fixture$$,'P0001','PAY_VIOLATION_LEDGER_INVALID','Mismatch between reviewed violation and ledger amount blocks approval');
