SELECT is((SELECT deduction_applied FROM public.violations WHERE id='a9500000-0000-4000-8000-000000000011'),true,'Violation state follows ledger in same transaction');
SELECT throws_ok($$SELECT public.transition_payroll_status_atomic(period_id,'approved') FROM payroll_fixture$$,'P0001','PAY_ALREADY_STATUS','Repeated approval cannot apply twice');
SELECT throws_ok($$SELECT public.calculate_payroll_atomic('a9500000-0000-4000-8000-000000000005',2026,2)$$,'P0001','PAY_CALCULATION_HISTORY_IMMUTABLE','Approved financial amounts cannot be recalculated');
