SELECT is((SELECT payroll_period_id FROM public.payroll_advances WHERE id=(SELECT advance_id FROM payroll_fixture)),(SELECT period_id FROM payroll_fixture),'Repaid advance keeps paid payroll reference');
SELECT throws_ok($$SELECT public.transition_payroll_status_atomic(period_id,'paid') FROM payroll_fixture$$,'P0001','PAY_ALREADY_STATUS','Repeated payment cannot repay twice');
SELECT throws_ok($$SELECT public.transition_payroll_status_atomic(period_id,'cancelled','Cannot undo paid history') FROM payroll_fixture$$,'P0001','PAY_TRANSITION_INVALID','Paid payroll cannot be cancelled without a financial reversal workflow');
SELECT is((public.payroll_periods_page(2026,0,'')->'stats'->>'net')::numeric,2175.94::numeric,'Live payroll KPI excludes the preserved cancelled revision');
SELECT set_config('request.jwt.claims','{"sub":"a9500000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
